class Poll:
    def __init__(self, question: str) -> None:
        self.question: str = question
        self._options: dict[str, int] = {}  # preserves insertion order, maps option -> votes
        self._total_votes: int = 0

    def add_option(self, option: str) -> None:
        if option not in self._options:
            self._options[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if option not in self._options:
            raise ValueError(f"Option '{option}' does not exist.")
        self._options[option] += 1
        self._total_votes += 1

    def winner(self) -> str | None:
        if self._total_votes < 3 or not self._options:
            return None

        # Determine the maximum vote count
        max_votes = max(self._options.values())

        # If there's a tie, the option added last wins.
        # Iterating in reverse order over insertion-ordered dict keys
        # finds the last-added option that has the maximum votes.
        for option, votes in reversed(list(self._options.items())):
            if votes == max_votes:
                return option

        return None
